import { useEffect, useRef, useState } from "react";
import {
  SHOPPING_LIST_CSV_URL,
  getShoppingList,
  getShoppingListText,
  type ShoppingRow,
} from "./api";

// Issue #30 — Export the shopping list as text and CSV.
//
// The list leaves the app the two ways that work on a plain-HTTP home network:
// Copy list (a plain-text preview + Copy button, to paste into whatever chat
// the person heading to the shop uses) and Export CSV (a shopping-list.csv
// download with Ingredient / Quantity / Notes). Both formats are generated by
// the backend so their fiddly bits — per-dish shares, CSV quoting, the UTF-8
// BOM — stay unit-tested behind the seam. There is deliberately no
// `navigator.share` path: it requires HTTPS, which this install doesn't have.

// The Copy-list modal: a read-only preview of the outstanding items plus a
// Copy button that puts the same text on the clipboard.
function CopyModal({
  text,
  onCopied,
  onClose,
}: {
  text: string;
  onCopied: () => void;
  onClose: () => void;
}) {
  const areaRef = useRef<HTMLTextAreaElement>(null);

  async function copy() {
    const area = areaRef.current;
    area?.focus();
    area?.select();
    try {
      await navigator.clipboard?.writeText(text);
    } catch {
      // Clipboard API unavailable (or blocked): the text is already selected,
      // so the person can copy it by hand. Either way we close on success.
    }
    onCopied();
  }

  return (
    <div
      className="modal-backdrop"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="modal">
        <h2>Copy list</h2>
        <p className="muted">
          Outstanding items, ready to paste into a message.
        </p>
        <textarea
          ref={areaRef}
          className="export-preview"
          readOnly
          rows={Math.min(16, text.split("\n").length + 1)}
          value={text}
        />
        <div className="modal-actions">
          <button className="btn" onClick={onClose}>
            Close
          </button>
          <button className="btn primary" onClick={copy}>
            Copy
          </button>
        </div>
      </div>
    </div>
  );
}

export function ShoppingList() {
  const [rows, setRows] = useState<ShoppingRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyText, setCopyText] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => {
    getShoppingList()
      .then(setRows)
      .catch((e: unknown) => setError(String(e)));
  }, []);

  function flash(message: string) {
    setToast(message);
    setTimeout(() => setToast(null), 2600);
  }

  async function openCopy() {
    try {
      setCopyText(await getShoppingListText());
    } catch (e: unknown) {
      setError(String(e));
    }
  }

  if (error) {
    return (
      <section className="library">
        <p className="error">Could not load the shopping list: {error}</p>
      </section>
    );
  }

  if (rows === null) {
    return (
      <section className="library">
        <p className="muted">Loading…</p>
      </section>
    );
  }

  const empty = rows.length === 0;

  return (
    <section className="library shopping">
      <header className="toolbar">
        <div>
          <h1>Shopping list</h1>
          <p className="muted">Shared by the whole household.</p>
        </div>
        <div style={{ display: "flex", gap: "0.5rem" }}>
          <button className="btn" disabled={empty} onClick={openCopy}>
            Copy list
          </button>
          {/* A plain anchor download: the CSV is served with a filename and a
              UTF-8 BOM, so no client-side blob juggling is needed. */}
          <a
            className={`btn primary${empty ? " disabled" : ""}`}
            href={SHOPPING_LIST_CSV_URL}
            download="shopping-list.csv"
            aria-disabled={empty}
            onClick={(e) => {
              if (empty) e.preventDefault();
              else flash("shopping-list.csv downloaded");
            }}
          >
            Export CSV
          </a>
        </div>
      </header>

      {empty ? (
        <p className="muted">
          Nothing on the list yet — add ingredients from a planned week.
        </p>
      ) : (
        <ul className="shopping-rows">
          {rows.map((row) => {
            const dishes = row.sources.filter((s) => s.dishTitle);
            const shared = dishes.length > 1;
            return (
              <li key={row.lineIds.join(",")} className="shopping-row">
                <span className="shopping-name">{row.name}</span>
                {row.totalQuantity && (
                  <span className="shopping-total">{row.totalQuantity}</span>
                )}
                <span className="shopping-chips">
                  {dishes.map((s, i) => (
                    <span key={i} className={`chip ${s.kind ?? ""}`}>
                      {s.kind === "known" ? "🍽" : "✨"} {s.dishTitle}
                      {shared ? ` ${s.share}` : ""}
                    </span>
                  ))}
                  {dishes.length === 0 && row.note && (
                    <span className="chip">✎ {row.note}</span>
                  )}
                </span>
              </li>
            );
          })}
        </ul>
      )}

      {copyText !== null && (
        <CopyModal
          text={copyText}
          onCopied={() => {
            setCopyText(null);
            flash("Copied to clipboard");
          }}
          onClose={() => setCopyText(null)}
        />
      )}
      {toast && <div className="toast">✓ {toast}</div>}
    </section>
  );
}
